import { act, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn(),
	close: vi.fn(),
	connect: vi.fn().mockResolvedValue(undefined),
	hostContext: {} as Record<string, unknown>,
	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));

vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener(name: string, handler: (params: unknown) => void) {
			bridge.listeners.get(name)?.delete(handler);
		}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() { return { theme: "light", ...bridge.hostContext }; }
		async openLink() { return { isError: false }; }
	},
	PostMessageTransport: class { close = bridge.close; },
}));

const originalParentDescriptor = Object.getOwnPropertyDescriptor(window, "parent");

describe("review race", () => {
	beforeEach(() => {
		vi.resetModules();
		vi.clearAllMocks();
		bridge.listeners.clear();
		bridge.hostContext = { toolInfo: { id: "old-card", tool: { name: "query_sdk" } } };
	});
	afterEach(() => {
		if (originalParentDescriptor) Object.defineProperty(window, "parent", originalParentDescriptor);
	});
	it("does not bind a fresh capability to an old in-flight host id", async () => {
		Object.defineProperty(window, "parent", { configurable: true, value: Object.assign(new EventTarget(), { location: { origin: "https://portable.example" } }) });
		let resolveOld!: (value: unknown) => void;
		const oldRestore = new Promise((resolve) => { resolveOld = resolve; });
		bridge.callServerTool.mockImplementation(async ({ name, arguments: args }) => {
			if (name === "restore_lobu_app_result" && !args.snapshot_capability) return oldRestore;
			if (name === "restore_lobu_app_result" && args.snapshot_capability === "new-cap") {
				return { isError: false, structuredContent: { found: true, tool_name: "query_sdk", data: { title: args.tool_call_id ? "OLD chosen by id" : "New card" }, view_state: {} } };
			}
			return { isError: false, structuredContent: { saved: false } };
		});
		const { Provider, useMcpApp } = await import("./host");
		function Probe() { const { data } = useMcpApp<{title: string}>(); return <span>{data?.title ?? "No result"}</span>; }
		render(<Provider devMock={{ title: "dev" }}><Probe /></Provider>);
		await waitFor(() => expect(bridge.callServerTool).toHaveBeenCalledWith({ name: "restore_lobu_app_result", arguments: { tool_call_id: "old-card", tool_name: "query_sdk" } }));
		act(() => { for (const handler of bridge.listeners.get("toolresult") ?? []) handler({ structuredContent: {}, _meta: { "lobu/mcp-app-snapshot-capability": "new-cap" } }); });
		expect(await screen.findByText("New card")).toBeInTheDocument();
		resolveOld({ isError: false, structuredContent: { found: true, tool_name: "query_sdk", data: { title: "Old card" }, view_state: {} } });
	});
});

