import { act, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn().mockResolvedValue({ isError: false }), close: vi.fn(),
	connect: vi.fn().mockResolvedValue(undefined), hostContext: {} as Record<string, unknown>,
	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));
vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) { const handlers = bridge.listeners.get(name) ?? new Set(); handlers.add(handler); bridge.listeners.set(name, handlers); }
		removeEventListener(name: string, handler: (params: unknown) => void) { bridge.listeners.get(name)?.delete(handler); }
		callServerTool = bridge.callServerTool; connect = bridge.connect;
		getHostContext() { return { theme: "light", ...bridge.hostContext }; }
		async openLink() { return { isError: false }; }
	}, PostMessageTransport: class { close = bridge.close; },
}));
const originalParent = Object.getOwnPropertyDescriptor(window, "parent");
const originalOpenai = Object.getOwnPropertyDescriptor(window, "openai");
describe("review stale echo", () => {
	beforeEach(() => { vi.resetModules(); vi.clearAllMocks(); bridge.listeners.clear(); bridge.hostContext = {}; });
	afterEach(() => { if (originalParent) Object.defineProperty(window, "parent", originalParent); if (originalOpenai) Object.defineProperty(window, "openai", originalOpenai); else Reflect.deleteProperty(window, "openai"); });
	it("does not resurrect a cleared result from a delayed widget-state echo", async () => {
		Object.defineProperty(window, "openai", { configurable: true, value: { toolOutput: { title: "Old card" }, setWidgetState: vi.fn() } });
		const parent = Object.assign(new EventTarget(), { location: { origin: window.location.origin } });
		Object.defineProperty(window, "parent", { configurable: true, value: parent });
		const { Provider, useMcpApp } = await import("./host");
		function Probe() { const { data } = useMcpApp<{title: string}>(); return <span>{data?.title ?? "No result"}</span>; }
		render(<Provider devMock={{ title: "dev" }}><Probe /></Provider>);
		expect(await screen.findByText("Old card")).toBeInTheDocument();
		act(() => { window.dispatchEvent(new CustomEvent("openai:set_globals", { detail: { globals: { toolOutput: null } } })); });
		expect(await screen.findByText("No result")).toBeInTheDocument();
		act(() => { window.dispatchEvent(new CustomEvent("openai:set_globals", { detail: { globals: { widgetState: { privateContent: { lobuViewSnapshot: { version: 1, data: { title: "Old card" } } } } } } })); });
		await waitFor(() => expect(screen.queryByText("Old card")).not.toBeInTheDocument());
	});
});

